use std::collections::BTreeSet;
#[test]
fn documented_flags_match_live_help(){let output=std::process::Command::new(env!("CARGO_BIN_EXE_docconvert")).arg("--help").output().unwrap();assert!(output.status.success());let help=String::from_utf8(output.stdout).unwrap();let live:BTreeSet<String>=help.lines().filter_map(|line|{let line=line.trim_start();if !line.starts_with('-'){return None}let at=line.find("--")?;Some(line[at..].chars().take_while(|c|c.is_ascii_alphanumeric()||*c=='-').collect())}).collect();let docs=include_str!("../docs/cli-reference.md");let mut written:BTreeSet<String>=docs.lines().filter(|l|l.starts_with("| `--")).map(|l|l.split('`').nth(1).unwrap().to_owned()).collect();if !cfg!(feature="pdf-layout"){written.remove("--pdfium-lib-path");}assert_eq!(live,written);}
